Here is an example script for a webapp that dynamically changes the order of items on a webpage based on the number of visits (clicks on the item). This script uses JavaScript and assumes that the items are stored in an array called "items".
```
<script>
  // Initialize an empty object to store the number of visits for each item
  var visits = {};

  // Function to track the number of visits for an item
  function trackVisit(item) {
    if (visits[item]) {
      visits[item]++;
    } else {
      visits[item] = 1;
    }
  }

  // Function to sort the items by number of visits
  function sortItemsByVisits() {
    items.sort(function(a, b) {
      if (visits[b] === visits[a]) {
        return 0;
      }
      return visits[b] > visits[a] ? 1 : -1;
    });
  }

  // Function to display the items
  function displayItems() {
    var itemList = document.getElementById("item-list");
    itemList.innerHTML = "";
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      var itemElement = document.createElement("div");
      itemElement.innerHTML = item;
      itemList.appendChild(itemElement);
    }
  }

  // Add event listeners to track visits on each item
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    item.addEventListener("click", function() {
      trackVisit(this.innerHTML);
      sortItemsByVisits();
      displayItems();
    });
  }

  // Initialize the display of items
  sortItemsByVisits();
  displayItems();
</script>
```
