using System;
using System.Net;
using System.IO;
using Newtonsoft.Json.Linq;

class RancherServiceInfo {
    static void Main(string[] args) {
        string serviceName = "my-service";
        string rancherUrl = "http://rancher-server:8080/v2-beta/projects/1a5/services/";
        string serviceUrl = rancherUrl + serviceName;

        HttpWebRequest request = (HttpWebRequest)WebRequest.Create(serviceUrl);
        request.Method = "GET";

        HttpWebResponse response = (HttpWebResponse)request.GetResponse();
        StreamReader reader = new StreamReader(response.GetResponseStream());
        string jsonResponse = reader.ReadToEnd();

        JObject serviceInfo = JObject.Parse(jsonResponse);
        string podName = serviceInfo["launchConfig"]["labels"]["io.kubernetes.pod.name"].Value<string>();
        string podIp = serviceInfo["launchConfig"]["labels"]["io.kubernetes.pod.ip"].Value<string>();

        Console.WriteLine("Pod name: " + podName);
        Console.WriteLine("Pod IP: " + podIp);
    }
}
