这里是使用广度优先搜索（BFS）从源顶点到目标顶点找到路径的C++解决方案：
```
#include <iostream>
#include <vector>
#include <queue>
using namespace std;
// 在给定具有n个顶点和表示为2D整数数组的边的双向图中确定是否存在源到目标的有效路径的函数
bool hasPath(int n, vector<vector<int>>& edges, int source, int destination) {
    // 创建图的邻接表表示
    vector<vector<int>> adj(n);
    for (const auto& edge : edges) {
        adj[edge[0]].push_back(edge[1]);
        adj[edge[1]].push_back(edge[0]);
    }
    // 使用BFS从源到目标找到路径
    queue<int> q;
    vector<bool> visited(n);
    q.push(source);
    visited[source] = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (u == destination) {
            //已到达目标顶点
            return true;
        }
        // 探索顶点u的所有邻居
        for (int v : adj[u]) {
            if (!visited[v]) {
                q.push(v);
                visited[v] = true;
            }
        }
    }
    // 从源到目标找不到路径
    return false;
}
int main() {
    int n = 3;
    vector<vector<int>> edges {{0, 1}, {1, 2}, {2, 0}};
    int source = 0;
    int destination = 2;
    if (hasPath(n, edges, source, destination)) {
        cout << "存在从顶点" << source << "到顶点" << destination << "的有效路径" << endl;
    } else {
        cout << "不存在从顶点" << source << "到顶点" << destination << "的有效路径" << endl;
    }
    return 0;
}
```
此解决方案的时间复杂度为O(n + m)，其中n是顶点数，m是图中的边数。空间复杂度为O(n)。

