  const [isExpanded, setIsExpanded] = useState(true);
  return (
    <Draggable handle=".handle">
      <Resizable
        className="text-md mb-4 ml-2 text-slate-600"
        style={{ backgroundColor: 'white', border: '1px solid lightgray', padding: '10px' }}
